//! The crates the binary contains and their licences: `resources/licenses/third-party.json`,
//! generated by `scripts/licenses.sh` from `cargo metadata` and `cargo tree`, compiled in.
//!
//! The list is read once. One that does not parse is empty; the tests keep that from shipping,
//! and they hold the list to `Cargo.lock`: a crate new to the lock file and missing here, or one
//! listed but no longer locked, fails them with the hint to run the script.

use std::sync::LazyLock;

use serde::Deserialize;

const THIRD_PARTY: &str = include_str!("../../../../resources/licenses/third-party.json");

static LIST: LazyLock<ThirdParty> =
    LazyLock::new(|| serde_json::from_str(THIRD_PARTY).unwrap_or_default());

/// The count per licence ([`counts`]), computed once.
static SUMMARY: LazyLock<Vec<(&'static str, usize)>> = LazyLock::new(|| summary(packages()));

/// The part of the generated list the page shows. The file also names the other crates of
/// `Cargo.lock` (`rust_not_shipped`: proc macros, build scripts, test helpers, what no built
/// platform reaches), which ship nowhere; only the tests read them.
#[derive(Debug, Default, Deserialize)]
struct ThirdParty {
    /// Every crate the binary links on a platform it is built for, by name and version.
    rust: Vec<Package>,
}

#[derive(Debug, Clone, PartialEq, Eq, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Package {
    pub name: String,
    pub version: String,
    /// The SPDX expression the crate declares, or the one `overrides.json` records for a crate
    /// that declares none.
    pub license: String,
}

/// The crates of the binary, by name.
pub fn packages() -> &'static [Package] {
    &LIST.rust
}

/// The crates whose name or licence contains `filter`, ignoring case; all for an empty one.
pub fn matching(filter: &str) -> impl Iterator<Item = &'static Package> {
    let filter = filter.trim().to_lowercase();
    packages().iter().filter(move |package| {
        filter.is_empty()
            || package.name.to_lowercase().contains(&filter)
            || package.license.to_lowercase().contains(&filter)
    })
}

/// How many crates carry each licence, most common first, then by name.
pub fn counts() -> &'static [(&'static str, usize)] {
    &SUMMARY
}

fn summary(packages: &[Package]) -> Vec<(&str, usize)> {
    let mut counts: Vec<(&str, usize)> = Vec::new();
    for package in packages {
        match counts
            .iter_mut()
            .find(|(license, _)| *license == package.license)
        {
            Some((_, count)) => *count += 1,
            None => counts.push((package.license.as_str(), 1)),
        }
    }
    counts.sort_by(|left, right| right.1.cmp(&left.1).then(left.0.cmp(right.0)));
    counts
}

